def get_fusion_for_unit(grade, unit_num, unit_title=""):
    key = (grade, unit_num)
    if key in FUSION_DATA:
        return FUSION_DATA[key]
    
    # Dynamic fallback based on keywords in title
    if "திருநீறு" in unit_title or "சின்னம்" in unit_title:
        return FUSION_DATA.get((2, 1))
    elif "கோயில்" in unit_title or "ஆலயம்" in unit_title:
        return FUSION_DATA.get((2, 2))
    elif "பஞ்ச பூதம்" in unit_title or "இயற்கை" in unit_title:
        return FUSION_DATA.get((3, 3))
    elif "உணவு" in unit_title or "சாத்வீக" in unit_title:
        return FUSION_DATA.get((4, 5))
    elif "கர்ம" in unit_title or "வினை" in unit_title:
        return FUSION_DATA.get((7, 4))
    elif "குறள்" in unit_title or "வள்ளுவர்" in unit_title:
        return FUSION_DATA.get((5, 3))
    elif "வேதம்" in unit_title or "உபநிடதம்" in unit_title:
        return FUSION_DATA.get((6, 1))
    
    # Default high-level fusion
    return {
        "science_correlation": f"அறிவாற்றல் நரம்பியல் & பிரபஞ்ச ஒருமைப்பாடு: இப்பாடத்தின் தத்துவக் கருத்துக்கள் நவீன மனோதத்துவவியல் மற்றும் அமைப்பியல் விதிகளோடு (Systems Dynamics) இயைந்து மன அமைதியையும் உயர்ந்த அறிவையும் தருகின்றன.",
        "world_application": f"21-ஆம் நூற்றாண்டு அறவாழ்வு: சவால்கள் நிறைந்த தற்காலச் சூழலில் தர்ம நெறிகளோடு கூடிய நெகிழ்வுத்தன்மையையும் (Emotional Resilience) நேர்மையான தலைமைத்துவத்தையும் உருவாக்குதல்.",
        "inquiry_lab": f"🔬 மாணவர் ஆய்வுப் பணி: இப்பாடத்தில் கற்ற நற்பண்பை உங்கள் அன்றாட செயல்களில் ஒன்றில் நடைமுறைப்படுத்தி அதனால் ஏற்பட்ட நேர்மறை மாற்றத்தைக் குறித்து வையுங்கள்."
    }
